  sub(ST("काव्यांश के आधार पर सही कथन चुनिए:", ["बीज ने अँधेरे में भी साहस नहीं खोया।", "बारिश और धूप के बाद अंकुर फूटा।", "कवि के अनुसार कष्ट सहे बिना ऊँचा स्थान मिल जाता है।", "वृक्ष बनकर वह सबको छाँव देता है।"], (0, 1, 3)), 1),
